/*
 * Komiic public API port, modified for Triomi's JS host (2026-10-29).
 * Derived from HyperionHXH/E-extensions Komiic Queries.kt, Entity.kt,
 * Payload.kt and Account.kt at 13df3c318e448c0295e0cf805b0c3755fbbb5fe0.
 * Apache-2.0; full license and upstream links are in this rule's attribution.
 * Guest access only by default. The host may supply a saved website session.
 * No password login, token refresh, account-success claim or quota bypass.
 * Website image quotas still apply, including during downloads.
 */
var KOMIIC_BASE = 'https://komiic.com';
var KOMIIC_COMIC = '{ id title description status imageUrl authors { id name } categories { id name } warnings }';

function komiicArray(value, label) {
  if (!Array.isArray(value)) throw new Error('Komiic ' + label + '格式不完整');
  return value;
}

function komiicText(value, label) {
  if (typeof value !== 'string' || !value.trim())
    throw new Error('Komiic ' + label + '缺失');
  return value;
}

async function komiicQuery(operationName, query, variables) {
  var response = await triomi.fetch(KOMIIC_BASE + '/api/query', {
    method: 'POST',
    headers: {'Content-Type': 'application/json', 'Referer': KOMIIC_BASE + '/'},
    bodyType: 'json',
    body: JSON.stringify({operationName: operationName, query: query, variables: variables})
  });
  if (response.status < 200 || response.status >= 300) {
    var reasons = {
      401: '未登录或会话已失效，请在应用内网页重新登录并保存会话',
      402: '今日图片读取额度已用尽，请等待网站重置',
      403: '网站拒绝访问，请在应用内网页检查访问权限',
      429: '网站限流，请稍后重试'
    };
    throw new Error('Komiic HTTP ' + response.status + '：' + (reasons[response.status] || '网站请求失败'));
  }
  var result;
  try { result = JSON.parse(response.body); }
  catch (_) { throw new Error('Komiic 返回的不是有效 JSON，请检查网站验证状态'); }
  if (!result || typeof result !== 'object') throw new Error('Komiic GraphQL 响应格式不完整');
  if (result.errors !== undefined) {
    var errors = komiicArray(result.errors, 'GraphQL 错误');
    if (errors.length) {
      throw new Error('Komiic GraphQL：' + errors.map(function(error) {
        var code = error && error.extensions && error.extensions.code;
        return (code ? String(code) + '：' : '') +
          (error && typeof error.message === 'string' ? error.message : '网站拒绝请求');
      }).join('；'));
    }
  }
  if (!result.data || typeof result.data !== 'object') throw new Error('Komiic GraphQL 缺少 data');
  return result.data;
}

function komiicItem(row) {
  if (!row || typeof row !== 'object') throw new Error('Komiic 作品格式不完整');
  var id = komiicText(row.id, '作品 ID');
  return {
    remoteId: id,
    title: komiicText(row.title, '作品标题'),
    url: KOMIIC_BASE + '/comic/' + encodeURIComponent(id),
    coverUrl: komiicText(row.imageUrl, '封面地址'),
    description: typeof row.description === 'string' ? row.description : '',
    author: komiicArray(row.authors, '作者').map(function(author) {
      return komiicText(author && author.name, '作者名称');
    }).join('，'),
    tags: komiicArray(row.categories, '分类').map(function(category) {
      return komiicText(category && category.name, '分类名称');
    }).concat(komiicArray(row.warnings, '内容提示')),
    status: row.status === 'END' ? 'completed' : row.status === 'ONGOING' ? 'ongoing' : 'unknown'
  };
}

async function discover(url, page) {
  var recent = /\/recent(?:[/?#]|$)/.test(url);
  var data = await komiicQuery('commonQuery',
    'query commonQuery($pagination: Pagination!) { comics: ' +
    (recent ? 'recentUpdate' : 'hotComics') + '(pagination: $pagination) ' + KOMIIC_COMIC + ' }',
    {pagination: {offset: ((page || 1) - 1) * 30,
      orderBy: recent ? 'DATE_UPDATED' : 'MONTH_VIEWS',
      status: '', asc: false, limit: 30, sexyLevel: null}, categoryId: []});
  return komiicArray(data.comics, '作品列表').map(komiicItem);
}

async function search(keyword, page) {
  // This endpoint is unpaged. Never repeat page one as an endless result list.
  if (page > 1) return [];
  var data = await komiicQuery('searchComicsAndAuthors',
    'query searchComicsAndAuthors($keyword: String!) { searchComicsAndAuthors(keyword: $keyword) { comics ' + KOMIIC_COMIC + ' } }',
    {keyword: keyword});
  if (!data.searchComicsAndAuthors) throw new Error('Komiic 搜索响应格式不完整');
  return komiicArray(data.searchComicsAndAuthors.comics, '搜索列表').map(komiicItem);
}

async function detail(url, item) {
  var match = /\/comic\/([^/?#]+)/.exec(url);
  var id = item && item.remoteId ? String(item.remoteId) : match && decodeURIComponent(match[1]);
  komiicText(id, '作品 ID');
  var data = await komiicQuery('mangaQuery',
    'query mangaQuery($comicId: ID!) { comicById(comicId: $comicId) ' + KOMIIC_COMIC +
    ' chaptersByComicId(comicId: $comicId) { id serial type size dateCreated } }', {comicId: id});
  var manga = komiicItem(data.comicById);
  var chapters = komiicArray(data.chaptersByComicId, '章节目录').map(function(row) {
    if (!row || typeof row !== 'object') throw new Error('Komiic 章节格式不完整');
    var chapterId = komiicText(row.id, '章节 ID');
    var serial = komiicText(row.serial, '章节序号');
    var type = komiicText(row.type, '章节类型');
    var number = Number(serial);
    return {
      remoteId: chapterId,
      title: type === 'chapter' ? '第 ' + serial + ' 話' : type === 'book' ? '第 ' + serial + ' 卷' : serial,
      url: manga.url + '/chapter/' + encodeURIComponent(chapterId) + '/images/all',
      number: isFinite(number) ? number : null,
      volumeTitle: type === 'chapter' ? '章节' : type === 'book' ? '单行本' : type,
      releaseDate: row.dateCreated,
      locked: false
    };
  });
  // Reading order is ascending within separate chapter/book editions, not interleaved.
  chapters.sort(function(a, b) {
    var ag = a.volumeTitle === '章节' ? 0 : a.volumeTitle === '单行本' ? 1 : 2;
    var bg = b.volumeTitle === '章节' ? 0 : b.volumeTitle === '单行本' ? 1 : 2;
    if (ag !== bg) return ag - bg;
    if (a.volumeTitle !== b.volumeTitle) return a.volumeTitle < b.volumeTitle ? -1 : 1;
    if (a.number !== b.number) {
      if (a.number === null) return 1;
      if (b.number === null) return -1;
      return a.number - b.number;
    }
    return a.remoteId < b.remoteId ? -1 : a.remoteId > b.remoteId ? 1 : 0;
  });
  return {item: manga, chapters: chapters};
}

async function content(url, chapter, options) {
  var match = /\/chapter\/([^/?#]+)/.exec(url);
  var id = chapter && chapter.remoteId ? String(chapter.remoteId) : match && decodeURIComponent(match[1]);
  komiicText(id, '章节 ID');
  var quotaData = await komiicQuery('imageLimit',
    'query imageLimit { getImageLimit { limit usage resetInSeconds } }', {});
  var quota = quotaData.getImageLimit;
  if (!quota || typeof quota.limit !== 'number' || typeof quota.usage !== 'number' ||
      !isFinite(quota.limit) || !isFinite(quota.usage) || quota.limit < 0 || quota.usage < 0)
    throw new Error('Komiic 图片额度响应格式不完整');
  if (quota.usage >= quota.limit) {
    var seconds = Number(quota.resetInSeconds);
    throw new Error('Komiic 今日图片读取额度已用尽（' + quota.usage + '/' + quota.limit + '），' +
      (isFinite(seconds) && seconds > 0 ? '约 ' + Math.ceil(seconds / 60) + ' 分钟后重置' : '请等待网站额度重置'));
  }
  var data = await komiicQuery('imagesByChapterId',
    'query imagesByChapterId($chapterId: ID!) { imagesByChapterId(chapterId: $chapterId) { kid } }',
    {chapterId: id});
  var pages = komiicArray(data.imagesByChapterId, '章节图片');
  if (!pages.length) throw new Error('Komiic 本章未提供可用图片，请检查网站访问权限或选择其他章节');
  return {
    images: pages.map(function(page) {
      return KOMIIC_BASE + '/api/image/' + encodeURIComponent(komiicText(page && page.kid, '图片 kid'));
    }),
    headers: {Referer: /^https:\/\/komiic\.com\/comic\//.test(url) ? url : KOMIIC_BASE + '/'}
  };
}
